inline const CreateItemProfile131* CreateItemProfileFor131(unsigned build){for(const auto& p:createItemProfiles131)if(p.build==build)return &p;return nullptr;}
inline bool CreateItemCode131(uintptr_t base,const CreateItemProfile131& p){ResourceTextProfile131 code{p.build,0,0,0,0,0,p.code,p.count};return ResourceTextGuard131(base,code);}
inline bool ParseCopyItem131(const std::wstring& args,unsigned& slot,unsigned& count){if(args.find(L'\0')!=args.npos||args.find_first_of(L"\r\n")!=args.npos)return false;std::wistringstream in(args);std::wstring value,rest;if(!(in>>value)||value.size()!=1||value[0]<L'1'||value[0]>L'6')return false;slot=unsigned(value[0]-L'1');std::getline(in,rest);return ParseUnitCount131(rest,count);}
using CreateItemNative131=uint32_t(__cdecl*)(uint32_t,const float*,const float*);
using ItemTypeNative131=uint32_t(__cdecl*)(uint32_t);
using ItemResolveNative131=uintptr_t(__cdecl*)(uint32_t);
inline uint32_t InvokeCreateItem131(CreateItemNative131 fn,uint32_t code,float x,float y){if(!fn||!code||!SpawnPoint131(x,y))return 0;__try{return fn(code,&x,&y);}__except(1){return 0;}}
inline uint32_t InvokeItemType131(ItemTypeNative131 fn,uint32_t handle){if(!fn||!handle)return 0;__try{return fn(handle);}__except(1){return 0;}}
inline uintptr_t InvokeItemResolve131(ItemResolveNative131 fn,uint32_t handle){if(!fn||!handle)return 0;__try{return fn(handle);}__except(1){return 0;}}
struct CreatedItemReference131 {uint32_t handle=0,code=0;uintptr_t item=0,node=0;DropObjectId id;};
inline bool SameCreatedItem131(const CreatedItemReference131& a,const CreatedItemReference131& b){return a.item&&a.node&&a.code&&a.id.Valid()&&a.handle==b.handle&&a.code==b.code&&a.item==b.item&&a.node==b.node&&a.id==b.id;}
inline bool ReadCreateItemContext131(uintptr_t base,unsigned build,ResourceCommandSource131& out){const auto* p=ResourceProfileFor131(build);if(!p||!ResourceCode131(base,*p))return false;__try{ResourceCommandSource131 v;v.world=ResourceWorld131(base,*p,v.local);if(!v.world||v.local>=24)return false;const auto player=reinterpret_cast<uintptr_t(__thiscall*)(uintptr_t,unsigned)>(base+p->playerFn);v.player=player(v.world,v.local);if(!ResourceIdentity131(v.player,base,p->playerTable)||*reinterpret_cast<int*>(v.player+p->statusOffset)!=1)return false;v.physical=*reinterpret_cast<unsigned char*>(v.player+p->idOffset);unsigned local=24;if(v.physical>=24||ResourceWorld131(base,*p,local)!=v.world||local!=v.local||player(v.world,local)!=v.player)return false;out=v;return true;}__except(1){return false;}}
inline bool ItemRegistryLive131(uintptr_t base,unsigned build,const CreatedItemReference131& value){const auto* rp=RemoveUnitProfileFor131(build);if(!rp||!value.id.Valid()||!value.node||!RemoveUnitCode131(base,*rp))return false;const auto node=ResolveRemoveUnitAgent131(base,*rp,value.id);__try{return node==value.node&&! *reinterpret_cast<uintptr_t*>(node+(sizeof(uintptr_t)==8?0x30:0x20));}__except(1){return false;}}
inline bool ReadCreatedItemObject131(uintptr_t base,unsigned build,uintptr_t item,CreatedItemReference131& out){const auto* p=InventoryProfile(build);const auto* rp=RemoveUnitProfileFor131(build);if(!p||!rp||!RemoveUnitCode131(base,*rp)||!ItemCodeGuard131(base,*p))return false;__try{CreatedItemReference131 v;v.item=item;if(!InventoryIdentity131(item,base,p->itemTable))return false;v.id=DropIdentity131(item);v.node=ResolveRemoveUnitAgent131(base,*rp,v.id);if(!ItemRegistryLive131(base,build,v))return false;v.code=ItemCodeValue131(base,*p,item);if(!v.code||!(DropIdentity131(item)==v.id)||!ItemRegistryLive131(base,build,v))return false;out=v;return true;}__except(1){return false;}}
inline bool ValidCreatedItem131(uintptr_t base,unsigned build,const CreatedItemReference131& expected){if(!ItemRegistryLive131(base,build,expected))return false;CreatedItemReference131 now;if(!ReadCreatedItemObject131(base,build,expected.item,now))return false;now.handle=expected.handle;return SameCreatedItem131(expected,now);}
inline bool ConfirmCreatedItem131(uintptr_t base,const CreateItemProfile131& p,uint32_t handle,uint32_t code,CreatedItemReference131& out){if(!handle||!CreateItemCode131(base,p))return false;const auto resolve=reinterpret_cast<ItemResolveNative131>(base+p.resolve);const auto item=InvokeItemResolve131(resolve,handle);CreatedItemReference131 v;if(!ReadCreatedItemObject131(base,p.build,item,v)||v.code!=code||InvokeItemType131(reinterpret_cast<ItemTypeNative131>(base+p.getType),handle)!=code||InvokeItemResolve131(resolve,handle)!=item)return false;v.handle=handle;if(!ValidCreatedItem131(base,p.build,v))return false;out=v;return true;}
struct CopyItemSource131 {RemoveUnitSource131 unit;uintptr_t inventory=0;unsigned slot=6,capacity=0;CreatedItemReference131 item;};
template<class Selected> bool ReadCopyItemSource131(uintptr_t base,unsigned build,unsigned slot,Selected selected,CopyItemSource131& out){const auto* p=InventoryProfile(build);if(!p||slot>=6)return false;const auto api=InventoryNative131(base,*p);CopyItemSource131 v;if(!api||!ReadRemoveUnit131(base,build,selected,v.unit))return false;__try{v.inventory=*reinterpret_cast<uintptr_t*>(v.unit.unit+p->inventoryOffset);if(!InventoryIdentity131(v.inventory,base,p->inventoryTable))return false;v.capacity=api.size(v.unit.unit);v.slot=slot;if(v.capacity>6||slot>=v.capacity||!ReadCreatedItemObject131(base,build,api.item(v.unit.unit,slot),v.item)||selected()!=v.unit.unit||!ValidRemoveUnit131(base,build,v.unit))return false;out=v;return true;}__except(1){return false;}}
template<class Selected> bool ValidCopyItemSource131(uintptr_t base,unsigned build,const CopyItemSource131& expected,Selected selected){if(!ValidRemoveUnit131(base,build,expected.unit)||!ValidCreatedItem131(base,build,expected.item))return false;CopyItemSource131 now;return ReadCopyItemSource131(base,build,expected.slot,selected,now)&&SameRemoveUnit131(expected.unit,now.unit)&&expected.inventory==now.inventory&&expected.capacity==now.capacity&&SameCreatedItem131(expected.item,now.item);}
template<class Read,class Source,class Create,class Confirm> bool CreateItemBatch131(uint32_t code,unsigned count,float x,float y,Read read,Source source,Create create,Confirm confirm,std::string& report){if(!code||count<1||count>50||!SpawnPoint131(x,y)||!SpawnPoint131(x+40.f*float(count-1),y)){report="Create Item: invalid type, count or coordinates";return false;}ResourceCommandSource131 owner,now;if(!read(owner)||!read(now)||!SameResourcePlayer131(owner,now)||!source(owner)){report="Create Item: stable local player/source required";return false;}std::array<CreatedItemReference131,50> made{};unsigned total=0;auto fail=[&](bool invoked){report="Create Item: "+std::to_string(total)+"/"+std::to_string(count)+" confirmed; stopped"+(invoked?" (latest call may have created an item)":" before next spawn");return false;};for(unsigned i=0;i<count;++i){if(!read(now)||!SameResourcePlayer131(owner,now)||!source(owner))return fail(false);const uint32_t handle=create(code,x+40.f*float(i),y);if(!handle)return fail(true);CreatedItemReference131 value;if(!confirm(handle,code,value)||value.handle!=handle||value.code!=code||!value.item||!value.node||!value.id.Valid()||!read(now)||!SameResourcePlayer131(owner,now)||!source(owner))return fail(true);for(unsigned j=0;j<total;++j)if(made[j].handle==handle||made[j].id==value.id)return fail(true);made[total++]=value;}report="Create Item: "+std::to_string(total)+"/"+std::to_string(count)+" created";return true;}
inline std::atomic_flag createItemBusy131=ATOMIC_FLAG_INIT;
template<class Allowed,class Selected,class Cursor> bool CreateOrCopyItemCommand131(uintptr_t base,unsigned build,const std::wstring& name,const std::wstring& args,Allowed allowed,Selected selected,Cursor cursor,std::string& report){const bool copy=name==L"#copyitem";uint32_t code=0;unsigned slot=6,count=1;if((name!=L"#item"&&!copy)||!(copy?ParseCopyItem131(args,slot,count):ParseCreateUnit131(args,code,count))){report=copy?"Usage: #copyitem slot(1..6) [1..50]":"Usage: #item rawcode [1..50]";return false;}if(!allowed()){report="Create Item: settings or session disabled";return false;}if(createItemBusy131.test_and_set()){report="Create Item: native batch already active";return false;}struct Release{~Release(){createItemBusy131.clear();}} release;const auto* p=CreateItemProfileFor131(build);if(!p||!CreateItemCode131(base,*p)){report="Create Item: native profile mismatch";return false;}ResourceCommandSource131 context;if(!ReadCreateItemContext131(base,build,context)){report="Create Item: active local player required";return false;}CopyItemSource131 original;if(copy){if(!ReadCopyItemSource131(base,build,slot,selected,original)||original.unit.world!=context.world||original.unit.local!=context.local){report="Copy Item: select a stable unit with an item in that slot";return false;}code=original.item.code;}MouseWorldPosition131 point;if(!cursor(point)||!SpawnPoint131(point.x,point.y)){report="Create Item: point the cursor at the map";return false;}const bool ok=CreateItemBatch131(code,count,point.x,point.y,[&](ResourceCommandSource131& out){return allowed()&&ReadCreateItemContext131(base,build,out);},[&](const ResourceCommandSource131& now){return allowed()&&SameResourcePlayer131(context,now)&&(!copy||ValidCopyItemSource131(base,build,original,selected));},[&](uint32_t type,float x,float y){return allowed()&&CreateItemCode131(base,*p)?InvokeCreateItem131(reinterpret_cast<CreateItemNative131>(base+p->create),type,x,y):0u;},[&](uint32_t handle,uint32_t type,CreatedItemReference131& out){return allowed()&&ConfirmCreatedItem131(base,*p,handle,type,out);},report);if(copy&&report.rfind("Create Item:",0)==0){report.replace(0,12,"Copy Item:");if(ok)report+=" (default charges)";}return ok;}
